var n=`0301-qofte`;var o=`world-0301`;var t=`AL`;var a=`southern-europe`;var l=4;var s=28;var r={en:`Qofte`,ua:`Кофте`};var d={en:`A traditional Albania dish made with ground lamb, ground beef, yellow onion, garlic. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Албанія. Основні інгредієнти: фарш з ягнятини, яловичий фарш, жовта цибуля, часник. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`ground-lamb`,350,`g`],[`ground-beef`,300,`g`],[`yellow-onion`,120,`g`],[`garlic`,3,`clove`],[`parsley`,25,`g`],[`dried-oregano`,4,`g`],[`table-salt`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 16 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 16 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:16,i:[[`extra-virgin-olive-oil`,55,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`plain-yogurt`,180,`g`]]}];var u={slug:n,id:o,country:`AL`,region:a,servings:4,minutes:28,title:r,text:d,steps:g};export{t as country,u as default,o as id,s as minutes,a as region,l as servings,n as slug,g as steps,d as text,r as title};